window.products.push({"id":1050303,"name":"Polder Countdown Timer","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/518A423ADWL._AC_.jpg","description":"Amazon.com If you've ever burned a pot roast or boiled a three-minute egg until it turned to rubber, you need a better timing system. The loud, 30-second alarm on this timer ensures that you won't forget to turn off the stove or rotate the turkey. It's also portable, and sticks on any metal surface, so if you have to leave the kitchen area, wafting smoke won't be the first reminder that a meal is ready. Easy to use and program, the timer comes with one AAA battery. --Laura Cuthbert","images":["https://m.media-amazon.com/images/I/518A423ADWL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Polder","source_asin":"B00004S4U9","category_path":"Home & Kitchen"},"sku":"BM-1050303","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00004S4U9","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00004S4U9","price_pending":true,"merchant_ready":false});
